for _e in ENTRIES:
    if _e.get("mnemonic"):
        continue
    if _e["title"] in _MNEMONICS:
        _e["mnemonic"] = _MNEMONICS[_e["title"]]
        continue
    _tagset = set(_e.get("tags", []))
    for _tag in _TAG_MNEMONIC_ORDER:
        if _tag in _tagset and _tag in _TAG_MNEMONICS:
            _e["mnemonic"] = _TAG_MNEMONICS[_tag]
            break

